import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum PageView {
  HOME = 'HOME',
  ABOUT = 'ABOUT',
  LOOKUP = 'LOOKUP',
  CONTACT = 'CONTACT'
}

export interface VehicleStats {
  originalBhp: number;
  tunedBhp: number;
  originalTorque: number;
  tunedTorque: number;
  vehicleName: string;
  engine: string;
}

export interface NavItem {
  label: string;
  view: PageView;
}

import { NavItem, PageView } from './types';

export const COMPANY_NAME = "Precision Remaps";
export const OWNER_NAME = "Chris";
export const EXPERIENCE_YEARS = 14;
export const LOCATION = "Paisley, Scotland";

// Placeholder for the logo provided in the prompt description
export const LOGO_URL = "logo.png.jpeg"; 

export const NAV_ITEMS: NavItem[] = [
  { label: 'Home', view: PageView.HOME },
  { label: 'Performance Lookup', view: PageView.LOOKUP },
  { label: 'About Us', view: PageView.ABOUT },
  { label: 'Contact', view: PageView.CONTACT },
];

import React from 'react';

interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: 'primary' | 'secondary' | 'outline';
  fullWidth?: boolean;
}

export const Button: React.FC<ButtonProps> = ({ 
  children, 
  variant = 'primary', 
  fullWidth = false, 
  className = '', 
  ...props 
}) => {
  const baseStyles = "font-bold py-3 px-6 rounded-lg transition-all duration-200 flex items-center justify-center gap-2";

  const variants = {
    primary: "bg-brand-orange hover:bg-orange-600 text-white shadow-[0_0_15px_rgba(255,102,0,0.3)] hover:shadow-[0_0_25px_rgba(255,102,0,0.5)]",
    secondary: "bg-brand-blue hover:bg-blue-700 text-white shadow-lg",
    outline: "border-2 border-brand-orange text-brand-orange hover:bg-brand-orange hover:text-white"
  };

  const widthClass = fullWidth ? "w-full" : "";

  return (
    <button 
      className={`${baseStyles} ${variants[variant]} ${widthClass} ${className}`} 
      {...props}
    >
      {children}
    </button>
  );
};

