const API_KEY = 'PASTE_YOUR_API_KEY_HERE'; 

// NOTE: Ensure this URL matches the specific endpoint for the MyChiptuningFiles API documentation you are using.
// Some APIs use /v1/specifications, others use /v1/vehicle/{reg}.
const API_BASE_URL = 'https://api.mychiptuningfiles.com/v1'; 

export const getVehicleStats = async (reg: string): Promise<VehicleStats> => {
  // 1. Validate Input
  if (!reg) throw new Error("Registration is required");
  const cleanReg = reg.replace(/\s/g, '').toUpperCase();

  try {
    // 2. Make API Request
    // Note: Calling this directly from the browser (Client-side) might trigger CORS errors 
    // depending on the API's configuration. Ideally, this runs on a backend proxy.
    const response = await fetch(`${API_BASE_URL}/vehicles?license_plate=${cleanReg}`, {
      method: 'GET',
      headers: {
        'Authorization': `Bearer ${API_KEY}`,
        'Accept': 'application/json',
        'Content-Type': 'application/json'
      }
    });

    // 3. Handle HTTP Errors
    if (!response.ok) {
        // If 404, throw the specific message requested
        if (response.status === 404) {
            throw new Error("Vehicle not found. Please contact Chris directly for a custom quote.");
        }
        throw new Error(`API Error: ${response.statusText}`);
    }

    const data = await response.json();

    // 4. Map API Response to App Interface
    // Note: These property names (make, model, standard_hp) are assumptions based on standard API structures.
    // You may need to console.log(data) to see the exact field names from MyChiptuningFiles and adjust below.

    // Check if we actually got vehicle data
    if (!data || (!data.make && !data.brand)) {
         throw new Error("Vehicle not found. Please contact Chris directly for a custom quote.");
    }

    const make = data.make || data.brand || 'Unknown Make';
    const model = data.model || 'Unknown Model';
    const engine = data.engine || data.motor || 'Unknown Engine';

    // Parse Stock Stats (Handle strings or numbers)
    const originalBhp = parseInt(data.standard_hp || data.power_hp || '0');
    const originalTorque = parseInt(data.standard_nm || data.torque_nm || '0');

    // 5. Calculate Gains (25% Logic)
    // If the API provides Stage 1 stats, use them. Otherwise, calculate +25%.
    const tunedBhp = data.stage1_hp 
        ? parseInt(data.stage1_hp) 
        : Math.round(originalBhp * 1.25);

    const tunedTorque = data.stage1_nm 
        ? parseInt(data.stage1_nm) 
        : Math.round(originalTorque * 1.25);

    // Validate sane numbers (if 0, likely bad data)
    if (originalBhp === 0) {
        throw new Error("Vehicle not found. Please contact Chris directly for a custom quote.");
    }

    return {
      vehicleName: `${make} ${model}`,
      engine: engine,
      originalBhp,
      tunedBhp,
      originalTorque,
      tunedTorque
    };

  } catch (error: any) {
    // Pass the specific error message up to the UI
    throw new Error(error.message || "Vehicle not found. Please contact Chris directly for a custom quote.");
  }
};

